function authErrorMessage(error){const raw=String(error?.message||'');if(/invalid login credentials|invalid email or password/i.test(raw))return 'That email and password did not match. Forgot your password? Reset it here.';if(/email not confirmed/i.test(raw))return 'Please confirm your email using the link we sent, then log in.';if(/already registered|user already registered/i.test(raw))return 'An account already uses this email. Log in or reset your password instead.';if(/invalid api key|apikey/i.test(raw))return 'Supabase rejected the public key. Check SUPABASE_URL and SUPABASE_ANON_KEY in .env.';return raw||'Authentication could not be completed. Please try again.';}
async function supabaseAuth(path,{method='POST',body,token}={}){if(!authConfig.configured)throw Error('Authentication is not configured yet. Add your Supabase project URL and public anon key to .env, then restart the local server.');const headers={'Content-Type':'application/json','apikey':authConfig.anonKey};if(token)headers.Authorization=`Bearer ${token}`;const response=await fetch(`${authConfig.supabaseUrl.replace(/\/$/,'')}/auth/v1/${path}`,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});let payload={};try{payload=await response.json()}catch{}if(!response.ok)throw Error(payload.msg||payload.message||payload.error_description||payload.error||`Authentication request failed (${response.status}).`);return payload;}
function storeAuthSession(session){if(session?.access_token)sessionStorage.setItem('aperture-auth-session',JSON.stringify(session));}
function base64url(bytes){let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function createPKCE(){const bytes=crypto.getRandomValues(new Uint8Array(48)),verifier=base64url(bytes),digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier));sessionStorage.setItem('aperture-auth-verifier',verifier);return base64url(new Uint8Array(digest));}
