async function finishAuthRedirect(){const params=new URLSearchParams(location.search),code=params.get('code'),error=params.get('error_description')||params.get('error');history.replaceState({},'',location.pathname);view='login';if(error){authNotice=error;render();return;}if(!code)return;try{const verifier=sessionStorage.getItem('aperture-auth-verifier');if(!verifier)throw Error('This sign-in link expired in this browser. Please request a new one.');const session=await supabaseAuth('token?grant_type=pkce',{body:{auth_code:code,code_verifier:verifier}});storeAuthSession(session);authBusy=false;sessionStorage.removeItem('aperture-auth-verifier');const purpose=sessionStorage.getItem('aperture-auth-purpose');sessionStorage.removeItem('aperture-auth-purpose');const userName=session.user?.user_metadata?.display_name||session.user?.user_metadata?.full_name;if(userName&&profile.name==='Aarav Sharma'){profile.name=userName;persist();}if(purpose==='recovery'){history.replaceState({},'','/reset-password');view='reset';authNotice='Your identity is confirmed. Choose a new password to finish the reset.';render();return;}history.replaceState({},'','/welcome');view='home';render();}catch(error){authNotice=authErrorMessage(error);render();}}
