 let content='';
 if(resetting){content=`<h2 id="auth-title">Reset your password</h2><form id="auth-reset-form"><label for="auth-new-password">New password</label><div class="auth-password"><input id="auth-new-password" name="password" type="${passwordVisible?'text':'password'}" autocomplete="new-password" minlength="8" required placeholder="At least 8 characters"><button type="button" data-action="auth-show-password" aria-label="${passwordVisible?'Hide password':'Show password'}">${passwordVisible?'Hide':'Show'}</button></div><div id="auth-message" class="auth-message" role="alert" aria-live="polite" ${authNotice?'':'hidden'}>${e(authNotice)}</div><button class="auth-primary" type="submit" ${authBusy?'disabled':''}>${authBusy?'Saving…':'Save new password'}</button></form>`;}
