async function bindAuth(){
 const emailInput=document.querySelector('#auth-form [name=email],#auth-signup-form [name=email]');
 emailInput?.addEventListener('input',event=>{authEmail=event.target.value});
 document.querySelectorAll('[data-action^="auth-"]').forEach(button=>button.addEventListener('click',async()=>{
  const action=button.dataset.action;
  try{
   if(action==='auth-show-password'){
    passwordVisible=!passwordVisible;
    const input=document.querySelector('#auth-password,#auth-signup-password,#auth-new-password');
    if(input)input.type=passwordVisible?'text':'password';
    button.textContent=passwordVisible?'Hide':'Show';
    button.setAttribute('aria-label',passwordVisible?'Hide password':'Show password');
    return;
   }
   if(action==='auth-demo'){navigate('home');return;}
   if(action==='auth-passkey'){authMessage('Passkeys are not enabled for this project yet. Use the email sign-in link, or configure a WebAuthn provider.');return;}
   if(['auth-google','auth-apple','auth-github'].includes(action)){await startOAuth(action.slice(5));return;}
   if(action==='auth-forgot'){
    authEmail=document.querySelector('#auth-form [name=email]')?.value?.trim()||authEmail;
    if(!authEmail){authMessage('Enter your email above first; we will keep it here while you reset your password.');document.querySelector('#auth-form [name=email]')?.focus();return;}
    authMessage('Sending a secure reset link…');await createPKCE();sessionStorage.setItem('aperture-auth-purpose','recovery');
    await supabaseAuth('recover?redirect_to='+encodeURIComponent(callbackURL()),{body:{email:authEmail}});
    authMessage('If an account exists for this email, a password reset link is on its way. Check your inbox.');return;
   }
   if(action==='auth-magic'){
    authEmail=document.querySelector('#auth-form [name=email]')?.value?.trim()||authEmail;
    if(!authEmail){authMessage('Enter your email above to receive a secure sign-in link.');document.querySelector('#auth-form [name=email]')?.focus();return;}
    authMessage('Sending your sign-in link…');await createPKCE();sessionStorage.setItem('aperture-auth-purpose','magic');
    await supabaseAuth('otp?redirect_to='+encodeURIComponent(callbackURL()),{body:{email:authEmail,create_user:true}});
    authMessage('Check your inbox for a secure sign-in link.');return;
   }
  }catch(error){authMessage(authErrorMessage(error));}
 }));
 document.querySelector('#auth-form')?.addEventListener('submit',async event=>{
  event.preventDefault();const values=new FormData(event.currentTarget);authEmail=String(values.get('email')||'').trim();const password=String(values.get('password')||'');
  authBusy=true;authMessage('Signing in securely…');
  try{const session=await supabaseAuth('token?grant_type=password',{body:{email:authEmail,password}});storeAuthSession(session);authBusy=false;const name=session.user?.user_metadata?.display_name||session.user?.user_metadata?.full_name;if(name&&profile.name==='Aarav Sharma'){profile.name=name;persist();}authNotice='';history.replaceState({},'','/welcome');view='home';render();}
  catch(error){authBusy=false;authMessage(authErrorMessage(error));const pass=document.querySelector('#auth-password');if(pass)pass.value='';document.querySelector('#auth-form [name=email]')?.focus();}
 });
 document.querySelector('#auth-signup-form')?.addEventListener('submit',async event=>{
  event.preventDefault();const values=new FormData(event.currentTarget);authEmail=String(values.get('email')||'').trim();const name=String(values.get('display_name')||'').trim(),password=String(values.get('password')||'');authBusy=true;authMessage('Creating your account securely…');
  try{await createPKCE();sessionStorage.setItem('aperture-auth-purpose','signup');const data=await supabaseAuth('signup?redirect_to='+encodeURIComponent(callbackURL()),{body:{email:authEmail,password,data:{display_name:name,account_type:location.pathname.includes('mentor')?'mentor':'user'}}});if(data.session){authBusy=false;storeAuthSession(data.session);sessionStorage.removeItem('aperture-auth-verifier');sessionStorage.removeItem('aperture-auth-purpose');profile.name=name;persist();authNotice='';history.replaceState({},'','/welcome');view='home';render();}else{authBusy=false;authMessage('Account created. Confirm your email using the link we sent, then log in.');}}
  catch(error){authBusy=false;authMessage(authErrorMessage(error));}
 });
 document.querySelector('#auth-reset-form')?.addEventListener('submit',async event=>{
  event.preventDefault();const password=String(new FormData(event.currentTarget).get('password')||'');
  try{const session=JSON.parse(sessionStorage.getItem('aperture-auth-session')||'{}');authBusy=true;authMessage('Updating your password…');await supabaseAuth('user',{method:'PUT',body:{password},token:session.access_token});sessionStorage.removeItem('aperture-auth-purpose');history.replaceState({},'','/login/user');view='login';authBusy=false;render();authMessage('Your password has been updated. Log in with your new password.');}
  catch(error){authBusy=false;authMessage(authErrorMessage(error));}
 });
}
function title(heading,subtitle,action=''){return `<div class="page-title"><div><h1>${heading}</h1><p>${subtitle}</p></div>${action}</div>`}
function analyticsPage(){return analyticsMarkup(profile,e,button,ratingHistory)}
function profilePage(){const rows=profile.projects||[],avatar=initials(profile.name||'A'),skillRows=skillEvidence(profile);return `${title(e(profile.name||'Professional profile'),e(profile.headline||'Learning in public · evidence over claims'),button('Edit profile','go-passport','secondary'))}<section class="profile-cover"><div class="profile-avatar large">${e(avatar)}</div><div><span class="class-kicker">APERTURE PROFESSIONAL PROFILE</span><h2>${e(profile.name)}</h2><p>${e(profile.headline||'Add a headline in your profile settings.')}</p><p>${e(profile.goal||'Tell people what you are curious about and what opportunity you hope to find next.')}</p><div class="tags">${profile.skills.map(s=>`<span class="tag">${e(s)}</span>`).join('')}</div></div></section><div class="profile-columns"><section class="card"><div class="card-header"><h2>About</h2><span class="badge self">YOU CONTROL THIS PROFILE</span></div><p class="intro">${e(profile.goal||'Add a short professional introduction, learning goals, or the type of opportunity you are exploring.')}</p></section><section class="card"><div class="card-header"><h2>Skills</h2><span class="count">${skillRows.filter(x=>x.projects.length).length} PROJECT-LINKED</span></div><div class="skill-evidence-list">${skillRows.map(x=>`<div><span>${e(x.skill)}</span><small class="badge ${x.projects.length?'project':'self'}">${x.projects.length?'Project evidence':'Self-reported'}</small></div>`).join('')||'Add skills in Edit profile.'}</div><p class="helper">Project links show where you described using a skill; they are not independent verification.</p></section></div><section class="card" style="margin-top:18px"><div class="card-header"><h2>Featured work</h2><span class="count">${rows.length} PROJECT${rows.length===1?'':'S'}</span></div>${rows.length?rows.map(p=>`<article class="profile-project"><div class="project-mark">${e(initials(p.title||'P'))}</div><div><h3>${e(p.title)}</h3><p>${e(p.description)}</p><div class="tags">${(p.skills||[]).map(s=>`<span class="tag">${e(s)}</span>`).join('')}</div><span class="badge ${p.evidenceType==='ai-video-reviewed'?'reviewed':'project'}">${p.evidenceType==='ai-video-reviewed'?'AI video reviewed · owner approved':'Project evidence'}</span></div></article>`).join(''):`<div class="empty"><h3>Show what you have made</h3><p>Add a project to make your skills easier to evaluate.</p>${button('Add profile details','go-passport','secondary')}</div>`}</section><div class="actions">${button('Open Skill Passport','go-passport','secondary')}${button('View skill analytics','go-analytics','text')}${button('Share profile','share-profile','text','link')}</div>`}
function mentorsPage(){return mentorsMarkup(social,e,button)}
function communitiesPage(){return communitiesMarkup(social,e)}
function home(){const evidenceSkills=[...new Set(profile.projects.flatMap(p=>p.evidenceType!=='self-reported-video'&&p.description.trim()?p.skills:[]))];const skills=[...new Set([...profile.skills,...evidenceSkills])];return `${title(t(`A little clarity. A bigger next step.`,`थोड़ी स्पष्टता। एक बड़ा अगला कदम।`),t(`Welcome back, ${e(profile.name.split(' ')[0])}. Let’s turn what you know into what’s next.`,`${e(profile.name.split(' ')[0])}, स्वागत है। जो सीखा है, उससे नई शुरुआत करें।`),`<span class="date-note">${t('YOUR JOURNEY, AT YOUR PACE','आपका सफ़र, आपकी रफ़्तार')}</span>`)}<section class="hero"><div class="hero-copy"><div class="eyebrow">${t('SHOW WHAT YOU CAN DO','आप क्या कर सकते हैं, दिखाएं')}</div><h2>${t('Your video.<br>Your skills. Your next step.','आपका वीडियो।<br>आपके कौशल। आपका अगला कदम।')}</h2><p>${t('Share a video of you doing an activity. Aperture AI drafts your skills form and shows what to improve next.','गतिविधि करते हुए अपना वीडियो दें। Aperture AI कौशल फॉर्म का ड्राफ़्ट और सुधार के अगले कदम तैयार करता है।')}</p>${button(t('Analyze my video','अपना वीडियो देखें'),'go-video','lime')}</div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 300 200"><defs><pattern id="dots" width="19" height="19" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".8" fill="#719076" opacity=".4"/></pattern></defs><rect x="0" y="0" width="300" height="200" fill="url(#dots)"/><circle cx="164" cy="99" r="84" stroke="#789571" stroke-dasharray="3 5" fill="none" opacity=".5"/><path d="M36 157V77h28v80M232 157V57h28v100" fill="#638465"/><path d="M50 85c45 0 42 69 100 69s57-89 97-89" stroke="#dcf0ae" stroke-width="4" fill="none"/><path d="M50 157h197" stroke="#d7e9ab" stroke-width="8"/><g stroke="#a8c28b" stroke-width="2"><path d="M77 101v56M103 131v26M128 149v8M177 146v11M201 119v38M224 79v78"/></g><path d="m148 67 13-13m-9 0h9v9" stroke="#cde39b" stroke-width="2" fill="none"/><circle cx="50" cy="77" r="5" fill="#d9ed9b"/><circle cx="247" cy="57" r="5" fill="#d9ed9b"/><path d="M23 178h251" stroke="#688569" opacity=".5"/></svg><div class="mini-float">✓ ${t('What you already know','आपका मौजूदा कौशल')}</div><div class="mini-float second">↗ ${t('Where you can go next','आपका अगला कदम')}</div></div></section><div class="journey">${[['video','01','Upload an activity video','गतिविधि का वीडियो दें','Auto-fill a skills form','कौशल फॉर्म अपने आप भरें'],['passport','02','Review your skill passport','स्किल पासपोर्ट देखें','Keep or edit your evidence','प्रमाण जांचें या बदलें'],['decoder','03','Find your next opportunity','अगला अवसर खोजें','See what to improve','क्या सुधारें जानें'],['mentor','04','Prepare with a mentor','मेंटर के साथ तैयारी','Discuss your next step','अगले कदम पर बात करें']].map(([id,no,en,hi,sub,subHi])=>`<button data-view="${id}"><span class="step-number">${no}</span><span><strong>${t(en,hi)}</strong><small>${t(sub,subHi)}</small></span></button>`).join('')}</div><div class="columns"><section class="card"><div class="card-header"><h2>${t('Your skills, with a story','आपके कौशल, आपकी कहानी')}</h2>${button(t('View passport','पासपोर्ट देखें'),'go-passport','text')}</div><div class="profile-summary"><div class="avatar">${e(initials(profile.name))}</div><div><h3>${e(profile.name)}</h3><p>${e(profile.headline)}</p></div></div>${skills.slice(0,4).map(s=>`<div class="evidence-row"><span><span class="skill-dot"></span>${e(s)}</span>${badge(evidenceSkills.includes(s)?'project':'self')}</div>`).join('')||'<p class="intro">Add your first skill to get started.</p>'}<div class="footnote">${icon('shield')}${t('Evidence, not a score. Your story stays yours.','प्रमाण, कोई स्कोर नहीं। आपकी कहानी आपकी है।')}</div></section><section class="card"><div class="card-header"><h2>${t('A good place to start','यहां से शुरुआत करें')}</h2><span class="count">${t('SAMPLE OPPORTUNITY','नमूना अवसर')}</span></div><div class="opportunity-head"><div class="opportunity-logo">${icon('leaf')}</div><div><h3>Frontend for Good</h3><p>${t('Student Developer · Sample brief','छात्र डेवलपर · नमूना विवरण')}</p></div></div><div class="tags"><span class="tag">${t('Beginner-friendly','शुरुआती छात्रों के लिए')}</span><span class="tag">${t('Web development','वेब डेवलपमेंट')}</span><span class="tag">${t('Project-based','प्रोजेक्ट आधारित')}</span></div><p class="opportunity-desc">${t('Help students discover campus opportunities. Build a responsive website, bring your curiosity, and learn with a team.','छात्रों को कैंपस के अवसर खोजने में मदद करें। एक वेबसाइट बनाएं, जिज्ञासु रहें और टीम के साथ सीखें।')}</p><div class="card-bottom"><span>HTML · CSS · JavaScript + 5</span>${button(t('Try this example','यह उदाहरण आज़माएं'),'sample-decode','secondary')}</div></section></div><section class="mentor-banner"><div class="icon-circle">${icon('chat').replace('<svg','<svg style="width:22px;height:22px"')}</div><div><h3>${t('Different experiences. Common ground.','अलग अनुभव। साझा समझ।')}</h3><p>${t('Prepare a clear, bilingual conversation with a mentor. Grow together.','मेंटर के साथ स्पष्ट, द्विभाषी बातचीत तैयार करें। साथ आगे बढ़ें।')}</p></div>${button(t('Prepare a conversation','बातचीत की तैयारी करें'),'go-mentor')}</section>`}
function videoForm(){const d=activityDraft;return `${title(t('Show us what you do.','आप क्या कर सकते हैं, दिखाएं।'),t('Upload a video. Aperture AI analyzes the activity, fills your form, and suggests specific ways to improve.','वीडियो दें। Aperture AI गतिविधि का विश्लेषण, फॉर्म और सुधार के खास सुझाव देगा।'))}<div class="notice ${aiConfigured?'':'amber'}"><strong>${aiConfigured?t('Vision AI is ready','वीडियो AI तैयार है'):t('Add your API key to enable video analysis','वीडियो विश्लेषण के लिए API key जोड़ें')}</strong> · ${aiConfigured?t('Your full video is sent to the selected AI provider only after you consent; Aperture AI requests deletion after analysis. Your key stays on the local server.','आपकी सहमति के बाद पूरा वीडियो चुने गए AI provider को भेजा जाता है; विश्लेषण के बाद Aperture AI उसे हटाने का अनुरोध करता है। आपकी key स्थानीय सर्वर पर सुरक्षित रहती है।'):t('Add your video-analysis API key to the local .env file, then restart Aperture AI. Do not put your key in this page or send it in chat.','स्थानीय .env फ़ाइल में video-analysis API key जोड़ें और Aperture AI दोबारा शुरू करें। Key यहां न डालें और चैट में न भेजें।')}</div><div class="two-panel"><section class="card"><div class="card-header"><h2>${t('1 · Choose your video','1 · अपना वीडियो चुनें')}</h2><span class="badge self">${t('Private preview','निजी प्रीव्यू')}</span></div><label class="upload-drop" for="activity-video"><span class="upload-icon">${icon('plus')}</span><strong>${t('Choose a video of any activity','किसी भी गतिविधि का वीडियो चुनें')}</strong><span>${t('MP4, MOV, or WebM · up to 100 MB','MP4, MOV या WebM · अधिकतम 100 MB')}</span><input type="file" id="activity-video" accept="video/mp4,video/quicktime,video/webm,video/*"></label>${activityVideoURL?`<div class="video-frame"><video controls playsinline preload="metadata" src="${activityVideoURL}" aria-label="${t('Your uploaded activity video','आपका गतिविधि वीडियो')}"></video><p>${e(activityFile.name)} · ${(activityFile.size/1024/1024).toFixed(1)} MB <button class="button text remove" data-action="remove-video" type="button">${t('Remove video','वीडियो हटाएं')}</button></p></div>`:''}<p class="helper">${t('Preview the full video here. After consent, Aperture AI sends the video to the selected AI provider so it can follow movement across the clip. Any audio track is sent with the video but is not used as evidence; Aperture AI requests deletion after analysis.','पूरा वीडियो यहीं प्रीव्यू करें। सहमति के बाद गतिविधि समझने के लिए वीडियो AI provider को भेजा जाता है। वीडियो के साथ ऑडियो ट्रैक भी जा सकता है, लेकिन प्रमाण के रूप में उसका उपयोग नहीं होगा; विश्लेषण के बाद Aperture AI उसे हटाने का अनुरोध करता है।')}</p></section><section class="card"><div class="card-header"><h2>${t('2 · Analyze and fill the form','2 · विश्लेषण और फॉर्म')}</h2><span class="badge self">${t('Review before saving','सहेजने से पहले जांचें')}</span></div><p class="intro">${t('No written description needed. The AI reviews the video, identifies the activity, fills in a skills form, and explains what to improve and how to practice it.','वीडियो का विवरण लिखने की ज़रूरत नहीं। AI गतिविधि पहचानकर फॉर्म भरता है और सुधार व अभ्यास समझाता है।')}</p><label class="consent-row"><input type="checkbox" id="video-consent" ${videoConsent?'checked':''} ${!activityVideoURL?'disabled':''}><span>${t('I agree to send this video to the selected AI provider for analysis. The video and any audio track are uploaded temporarily; Aperture AI requests deletion after analysis. API usage may incur charges.','मैं सहमत हूं कि विश्लेषण के लिए यह वीडियो चुने गए AI provider को भेजा जाए। वीडियो और उसका ऑडियो ट्रैक अस्थायी रूप से अपलोड होते हैं; विश्लेषण के बाद हटाने का अनुरोध किया जाता है। API शुल्क लग सकता है।')} <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">${t('Privacy details','गोपनीयता जानकारी')}</a></span></label><div class="actions"><button class="button" type="button" data-action="analyze-video" ${!activityVideoURL||!videoConsent||!aiConfigured||busy?'disabled':''}>${busy?t('Analyzing the video…','वीडियो का विश्लेषण…'):t('Analyze video & fill my form','वीडियो देखें और फॉर्म भरें')}${icon('spark')}</button></div><p class="helper">${t('The model may miss details. Skills and improvement advice are AI suggestions, not a score or certification. You can edit every field.','AI कुछ बातें छोड़ सकता है। कौशल और सुधार के सुझाव कोई स्कोर या प्रमाणपत्र नहीं हैं। हर फ़ील्ड बदल सकते हैं।')}</p></section></div>${d?`<section id="activity-generated" class="card" style="margin-top:20px"><div class="card-header"><div><h2>${t('3 · Review your auto-filled form','3 · भरा हुआ फॉर्म जांचें')}</h2><p class="helper">${t('Generated from the video · editable before adding to your passport','वीडियो से बना · पासपोर्ट में जोड़ने से पहले बदलें')}</p></div><span class="badge self">${t('AI-generated draft','AI का ड्राफ़्ट')}</span></div><div class="notice amber">${d.videoName?e(d.videoName)+' · ':''}${t('Video analysis draft','वीडियो विश्लेषण ड्राफ़्ट')} · ${t('Suggestions are AI-generated. Verify them with a trusted coach or reliable activity-specific guidance.','सुझाव AI ने बनाए हैं। इन्हें भरोसेमंद कोच या गतिविधि के विश्वसनीय मार्गदर्शन से मिलाएं।')}</div><div class="activity-observations"><h3>${t('What the model observed','AI ने क्या देखा')}</h3><p>${e(d.description)}</p><div class="tags">${d.skills.map(x=>`<span class="tag">${e(x.name)} · ${t('practice rating','अभ्यास रेटिंग')} ${x.rating!==undefined&&x.rating!==null&&String(x.rating).trim()!==''&&Number.isFinite(Number(x.rating))&&Number(x.rating)>=1?`${Math.max(1,Math.min(100,Number(x.rating)))}/100 · ${e(x.confidence)}`:t('rating not returned · not scored','रेटिंग नहीं मिली · स्कोर नहीं किया गया')}</span>`).join('')||t('No clear skill evidence detected.','कौशल का स्पष्ट प्रमाण नहीं मिला।')}</div>${d.skills.map(x=>`<p class="source"><strong>${e(x.name)} · ${e(x.evidence_time||'not timestamped')}:</strong> ${e(x.visible_evidence)}</p>`).join('')}</div><form id="activity-form"><div class="form-grid"><div class="field"><label>${t('Activity name','गतिविधि का नाम')}<input name="title" value="${e(d.title)}" required maxlength="120"></label></div><div class="field"><label>${t('Skills to add','जोड़ने के कौशल')}<input name="skills" value="${e(d.skills.map(x=>x.name).join(', '))}" maxlength="500"></label></div><div class="field full"><label>${t('Activity summary · Passport description','गतिविधि · पासपोर्ट विवरण')}<textarea name="description" required minlength="12" maxlength="3000">${e(d.description)}</textarea></label></div></div><h3 style="margin:10px 0">${t('Improvement suggestions','सुधार के सुझाव')}</h3>${d.strengths.length?`<div class="notice">${t('Strengths noticed','देखी गई खूबियां')}: ${e(d.strengths.join(' · '))}</div>`:''}${d.improvements.map((x,i)=>`<div class="improvement-item"><span class="step-number">${i+1}</span><div><strong>${e(x.step)}</strong><p>${e(x.why)}</p><p><b>${t('Try next:','अगली बार:')}</b> ${e(x.practice)}</p>${x.safety_note?`<p class="helper">${e(x.safety_note)}</p>`:''}</div></div>`).join('')||`<p class="helper">${t('No specific improvement could be identified from these frames.','इन फ़्रेम से खास सुधार पहचानना संभव नहीं हुआ।')}</p>`}${d.standard_note?`<div class="notice amber">${e(d.standard_note)}</div>`:''}${d.uncertainty.length?`<div class="notice">${t('Uncertainty','अनिश्चितता')}: ${e(d.uncertainty.join(' · '))}</div>`:''}<div class="field"><label>${t('Edit or add a next practice step','अगला अभ्यास बदलें या जोड़ें')}<textarea name="improvement" maxlength="1000">${e(d.improvements.map(x=>'• '+x.step+' — '+x.why+' Try next: '+x.practice+(x.safety_note?' Safety: '+x.safety_note:'')).join('\n'))}</textarea></label></div><div class="notice amber">${t('Review the AI draft. This is not an independent review. Save only accurate details. For safety-sensitive activities, follow a qualified coach or official guidance.','AI ड्राफ़्ट जांचें। यह स्वतंत्र समीक्षा नहीं है। सही जानकारी ही सहेजें। सुरक्षा-संवेदनशील गतिविधियों में योग्य कोच या आधिकारिक मार्गदर्शन लें।')}</div><div class="actions"><button class="button" type="submit">${t('Add reviewed form to Skill Passport','जांचा हुआ फॉर्म पासपोर्ट में जोड़ें')}${icon('check')}</button><button class="button secondary" type="button" data-action="discard-activity">${t('Discard draft','ड्राफ़्ट हटाएं')}</button></div></form></section>`:''}`}


function passport(){return `${title(t('Your skills deserve a story.','आपके कौशल की भी एक कहानी है।'),t('Make what you’ve learned visible. Add context, projects, and evidence.','जो सीखा है, उसे दिखाएं। संदर्भ, प्रोजेक्ट और प्रमाण जोड़ें।'),button(t('Preview passport','पासपोर्ट प्रीव्यू'),'go-preview'))}<div class="two-panel"><section class="card"><div class="card-header"><h2>${t('A little about you','आपके बारे में')}</h2><span class="badge self">${t('Sample profile · editable','नमूना प्रोफ़ाइल · संपादन योग्य')}</span></div><form id="profile-form"><div class="field"><label>${t('Name','नाम')}<input name="name" required maxlength="80" value="${e(profile.name)}"></label></div><div class="field"><label>${t('Headline','परिचय')}<input name="headline" required maxlength="150" value="${e(profile.headline)}"></label></div><div class="field"><label>${t('What would you like to do next?','आगे क्या करना चाहते हैं?')}<textarea name="goal" maxlength="1200">${e(profile.goal)}</textarea></label></div><div class="field"><label>${t('Skills · separated by commas','कौशल · कॉमा से अलग करें')}<input name="skills" maxlength="1000" value="${e(profile.skills.join(', '))}"></label><p class="helper">${t('These are self-reported until you link a project that demonstrates them.','प्रोजेक्ट प्रमाण जोड़ने तक ये स्वयं बताए गए कौशल हैं।')}</p></div><button class="button" type="submit">${t('Save profile','प्रोफ़ाइल सहेजें')}${icon('check')}</button></form></section><section class="card"><div class="card-header"><h2>${t('Projects & learning','प्रोजेक्ट और सीख')}</h2>${button(t('Add project','प्रोजेक्ट जोड़ें'),'add-project','secondary','plus')}</div><p class="intro">${t('Tell us what you built and what you contributed. Project labels reflect your description, not independent verification.','बताएं कि आपने क्या बनाया और आपका योगदान क्या था। ये लेबल आपके विवरण पर आधारित हैं, स्वतंत्र सत्यापन पर नहीं।')}</p>${projectCards(profile,true)}<div class="legend">${badge('self')}${badge('project')}${badge('reviewed')}</div><p class="helper">${t('No independent reviews have been recorded in this prototype.','इस प्रोटोटाइप में कोई स्वतंत्र समीक्षा दर्ज नहीं है।')}</p></section></div><div class="actions">${button(t('Next: decode an opportunity','अगला: अवसर समझें'),'go-decoder')}${button(t('Download passport','पासपोर्ट डाउनलोड करें'),'export','secondary','passport')}</div>`}
function projectCards(p,editable=false){return p.projects.map((x,i)=>`<article class="project-card"><div class="project-top"><h3>${e(x.title)}</h3>${badge(x.evidenceType==='self-reported-video'?'self':'project')}</div><p>${e(x.description)}</p><div class="tags">${x.skills.map(s=>`<span class="tag">${e(s)}</span>`).join('')}</div>${x.achievement?`<p>↗ ${e(x.achievement)} ${badge('self')}</p>`:''}${x.artifactLabel?`<p class="helper">▣ ${e(x.artifactLabel)} · ${t('Video stayed on this device and is not in this passport.','वीडियो इसी डिवाइस पर रहा, पासपोर्ट में शामिल नहीं है।')}</p>`:''}${x.improvements?.length?`<p><strong>${t('Next improvements','अगले सुधार')}</strong></p><ul>${x.improvements.map(v=>`<li>${e(v)}</li>`).join('')}</ul>`:''}${safeURL(x.url)?`<p><a class="inline-link" href="${e(safeURL(x.url))}" target="_blank" rel="noopener noreferrer">${t('View project','प्रोजेक्ट देखें')} ↗</a></p>`:`<p class="helper">${t('Description only · No external artifact attached','केवल विवरण · कोई बाहरी प्रोजेक्ट लिंक नहीं')}</p>`}${editable?`<div class="actions"><button class="button text" data-edit="${i}">${t('Edit','संपादित करें')}</button><button class="button text remove" data-remove="${i}">${t('Remove','हटाएं')}</button></div>`:''}</article>`).join('')||`<div class="empty"><p>${t('Your first project can be small. Add something you built or learned.','आपका पहला प्रोजेक्ट छोटा हो सकता है। कुछ जोड़ें जो आपने बनाया या सीखा।')}</p></div>`}
function decoder(){const r=result();return `${title(t('Turn a brief into a clear path.','अवसर समझें, रास्ता बनाएं।'),t('Understand the expectations. Connect the evidence. Choose your next step.','अपेक्षाएं समझें। प्रमाण जोड़ें। अपना अगला कदम चुनें।'))}<section class="card"><div class="card-header"><h2>${t('Paste an opportunity','अवसर का विवरण पेस्ट करें')}</h2><div class="actions" style="margin:0">${button(t('English example','अंग्रेज़ी उदाहरण'),'load-en','text')}${button(t('Hindi example','हिन्दी उदाहरण'),'load-hi','text')}</div></div><form id="decode-form"><label for="opportunity">${t('Job description, research opportunity, or hackathon brief · Hindi or English','नौकरी, शोध अवसर या हैकाथॉन विवरण · हिन्दी या अंग्रेज़ी')}</label><textarea class="large" id="opportunity" name="opportunity" required minlength="20" maxlength="12000">${e(opportunity)}</textarea><p class="helper">${t('Offline, rule-based demo. Recognizes 10 common skills; review the full source for anything it misses. Your text stays in this browser.','ऑफ़लाइन नियम-आधारित डेमो। 10 सामान्य कौशल पहचानता है; छूटी बातों के लिए पूरा विवरण पढ़ें। आपका टेक्स्ट इसी ब्राउज़र में रहता है।')}</p><div class="actions"><button class="button" ${busy?'disabled':''}>${icon('spark')}${busy?t('Decoding…','समझ रहे हैं…'):t('Decode opportunity','अवसर समझें')}</button></div></form></section>${decoded?`<div class="section-stack" style="margin-top:20px"><section class="card"><div class="card-header"><h2>${t('Here’s what it’s asking for','यह अवसर आपसे क्या चाहता है')}</h2><span class="badge self">${t('Generated · rule-based demo','जनरेट किया गया · नियम-आधारित डेमो')}</span></div><label>${t('Editable plain-language explanation','सरल व्याख्या · संपादन योग्य')}<textarea id="plain-summary">${e(drafts['plain-'+lang]??plainSummary(r))}</textarea></label><p class="helper">${t('Interpretation, not an eligibility decision. Check every requirement against the original brief.','यह व्याख्या है, पात्रता का निर्णय नहीं। हर अपेक्षा मूल विवरण से जांचें।')}</p></section><section class="card"><h2>${t('Requirements ↔ your evidence','अपेक्षाएं ↔ आपके प्रमाण')}</h2><p class="intro" style="margin-top:8px">${t('Missing evidence means your current passport doesn’t show it yet. It says nothing about your potential.','प्रमाण न होने का मतलब है कि पासपोर्ट में वह अभी दिखता नहीं। यह आपकी क्षमता का निर्णय नहीं है।')}</p><div class="result-summary">${['demonstrated','partial','missing'].map(s=>`<span class="status ${s}">${r.requirements.filter(x=>x.status===s).length} ${statusName(s)}</span>`).join('')}</div>${r.requirements.map(x=>`<div class="requirement"><div><h3>${e(x.id)} <span class="tag">${e(t(x.priority,x.priority==='Required'?'आवश्यक':x.priority==='Preferred'?'वांछनीय':'उल्लेखित'))}</span></h3><p class="muted" style="font-size:12px">${e(t(x.plain,x.hi))}</p><div class="source"><strong>${t('From your brief:','मूल विवरण से:')}</strong> “${e(x.source)}”</div></div><div><span class="status ${x.status}">${statusName(x.status)}</span><p class="evidence-detail">${x.evidence.length?`${t('Linked description:','जुड़ा विवरण:')} ${e(x.evidence.join(', '))}`:x.status==='partial'?t('Listed in your skills. Add a project example to show how you use it.','कौशल सूची में मौजूद है। इसके इस्तेमाल का प्रोजेक्ट उदाहरण जोड़ें।'):t('No matching project or claim in your current passport.','मौजूदा पासपोर्ट में इससे मिलता प्रोजेक्ट या दावा नहीं है।')}</p></div></div>`).join('')||`<div class="empty"><h3>${t('No recognized skills found','कोई परिचित कौशल नहीं मिला')}</h3><p>${t('This demo has a limited vocabulary. Keep the original brief and discuss its requirements with a mentor. Try a sample to see the connected flow.','इस डेमो की शब्दावली सीमित है। मूल विवरण में अपेक्षाएं मेंटर के साथ समझें। पूरा फ़्लो देखने के लिए उदाहरण आज़माएं।')}</p></div>`}<div class="notice amber" style="margin-top:18px;margin-bottom:0">${t('Extraction may be incomplete. Mixed required/preferred clauses and skills outside this demo’s vocabulary need a manual check.','जानकारी अधूरी हो सकती है। एक ही वाक्य में आवश्यक/वांछनीय कौशल और शब्दावली से बाहर की अपेक्षाएं खुद जांचें।')}${r.unrecognized.length?`<p style="margin-top:8px">${t('Unmapped source text:','बिना मैप किया मूल टेक्स्ट:')} ${e(r.unrecognized.join(' · '))}</p>`:''}</div></section>${actionPlan(r)}<div class="actions">${button(t('Next: create a bilingual summary','अगला: द्विभाषी सारांश बनाएं'),'go-bridge')}${button(t('Update my evidence','मेरे प्रमाण बदलें'),'go-passport','secondary')}</div></div>`:''}`}
function plainSummary(r){if(!r.requirements.length)return t('No familiar skills were detected. Read the original opportunity with a mentor and identify the tasks, expectations, and evidence requested.','कोई परिचित कौशल नहीं मिला। मेंटर के साथ मूल अवसर पढ़ें और काम, अपेक्षाएं तथा मांगे गए प्रमाण पहचानें।');return t('This brief mentions the following work: ','इस विवरण में इन कामों का उल्लेख है: ')+r.requirements.map(x=>t(x.plain,x.hi)).join('; ')+t('. Use a project to explain what you have tried, what you contributed, and what you want to learn. Check the original brief for deadlines and other conditions.','। अपने प्रोजेक्ट से बताएं कि आपने क्या किया, आपका योगदान क्या था और आप क्या सीखना चाहते हैं। समय सीमा और अन्य शर्तें मूल विवरण में जांचें।')}
function actionPlan(r){const gaps=r.requirements.filter(x=>x.status!=='demonstrated');return `<section class="card"><div class="card-header"><h2>${t('“Why am I not ready yet?”','“मैं अभी तैयार क्यों नहीं हूं?”')}</h2><span class="count">${t('YOUR NEXT STEPS','आपके अगले कदम')}</span></div><p class="intro">${t('You don’t need a readiness score. Here is the proof your current profile is missing, and a small way to build it. You can still explore or apply.','आपको तैयारी का स्कोर नहीं चाहिए। ये वे प्रमाण हैं जो अभी प्रोफ़ाइल में नहीं हैं और उन्हें बनाने के छोटे कदम हैं। आप फिर भी अवसर देख सकते हैं या आवेदन कर सकते हैं।')}</p>${gaps.map(x=>`<div class="plan-item ${completed.includes(x.id)?'done':''}"><input type="checkbox" id="plan-${e(x.id)}" data-plan="${e(x.id)}" ${completed.includes(x.id)?'checked':''}><label for="plan-${e(x.id)}"><strong>${e(x.id)} · ${t(x.priority,x.priority==='Preferred'?'वांछनीय':x.priority==='Required'?'आवश्यक':'उल्लेखित')}</strong><p>${e(t(x.step,x.stepHi))}</p></label></div>`).join('')||`<p class="intro">${r.requirements.length?t('Your project descriptions cover all recognized skills. Review the full brief, attach actual artifacts, and ask a mentor for feedback.','प्रोजेक्ट विवरण में सभी पहचाने कौशल शामिल हैं। पूरा विवरण जांचें, प्रोजेक्ट लिंक जोड़ें और मेंटर की प्रतिक्रिया लें।'):t('Start by identifying the requirements with a mentor.','मेंटर के साथ अपेक्षाएं पहचानने से शुरुआत करें।')}</p>`}<p class="helper">${t('Checking a step tracks your plan; it does not verify a skill or change your evidence status.','चेक करने से सिर्फ योजना की प्रगति दर्ज होती है; कौशल सत्यापित नहीं होता और प्रमाण का स्तर नहीं बदलता।')}</p></section>`}
const TRANSLATIONS=[
[INITIAL.goal,'उपयोगी चीज़ें बनाना और अपना पहला व्यावहारिक अवसर खोजना।'],
[INITIAL.headline,'प्रथम वर्ष का छात्र · जिज्ञासु निर्माता'],
[INITIAL.projects[0].description,'HTML और CSS से बनाया गया एक रिस्पॉन्सिव कैंपस इवेंट पेज। मैंने क्लब के अनुसार इवेंट खोजने के लिए JavaScript फ़िल्टर लिखे।'],
[INITIAL.projects[0].achievement,'अपनी पहली रिस्पॉन्सिव वेबसाइट बनाई'],
['I want to learn Git and work with a team.','मैं Git सीखना चाहता हूं और टीम के साथ काम करना चाहता हूं।'],
['Please share a project demo and explain your contribution.','कृपया प्रोजेक्ट का डेमो साझा करें और अपना योगदान समझाएं।']
];
function translateKnown(text,language){const row=TRANSLATIONS.find(pair=>pair.includes(text.trim()));return row?row[language==='hi'?1:0]:text;}
function bilingualText(language){const r=result();const hi=language==='hi';const rows=r.requirements.map(x=>`${x.id}: ${hi?x.hi:x.plain} — ${hi?(x.status==='demonstrated'?'प्रोजेक्ट विवरण मौजूद':x.status==='partial'?'स्वयं बताया; प्रोजेक्ट प्रमाण जोड़ें':'अभी प्रमाण नहीं'):(x.status==='demonstrated'?'project description available':x.status==='partial'?'self-reported; add project evidence':'not yet evidenced')}`);return `${hi?'नमस्ते, मेरा नाम':'Hi, I’m'} ${profile.name}.\n\n${hi?'मेरा लक्ष्य:':'My goal:'} ${translateKnown(profile.goal,language)}\n\n${hi?'अवसर की अपेक्षाएं:':'Opportunity expectations:'}\n${rows.join('\n')|| (hi?'पहले अवसर का विवरण जोड़ें।':'Add an opportunity first.')}\n\n${hi?'मेरा प्रोजेक्ट:':'My project:'} ${profile.projects[0]?.title|| (hi?'अभी नहीं जोड़ा':'Not added yet')}\n${hi?'प्रोजेक्ट विवरण:':'Project description:'} ${translateKnown(profile.projects[0]?.description||'—',language)}\n\n${hi?'मेंटर से सवाल: मैं अपने काम का कौन सा प्रमाण पहले जोड़ूं?':'Question for my mentor: Which piece of evidence should I add first?'}`}
function bridge(){return `${title(t('Your work. In more than one language.','आपका काम। दोनों भाषाओं में।'),t('Prepare an English and Hindi explanation you can make your own.','अंग्रेज़ी और हिन्दी में अपनी बात तैयार करें।'))}<div class="notice amber">${t('Offline template mode, not a general AI translator. Known skill explanations and sample profile phrases are translated; other free text is preserved in its original language. Edit both versions before sharing.','यह ऑफ़लाइन टेम्पलेट है, सामान्य AI अनुवादक नहीं। परिचित कौशल और नमूना प्रोफ़ाइल वाक्यों का अनुवाद होता है; अन्य टेक्स्ट मूल भाषा में रहता है। साझा करने से पहले दोनों संस्करण संपादित करें।')}</div>${!decoded?`<div class="notice">${t('Decode an opportunity first to include its requirements. You can still prepare your profile introduction.','अपेक्षाएं शामिल करने के लिए पहले अवसर समझें। अभी भी अपना परिचय तैयार कर सकते हैं।')}${button(t('Open decoder','डिकोडर खोलें'),'go-decoder','text')}</div>`:''}<section class="card"><div class="card-header"><h2>${t('Bilingual conversation card','द्विभाषी संवाद कार्ड')}</h2>${button(t('Generate / refresh','बनाएं / रीफ़्रेश करें'),'generate-bridge','secondary','spark')}</div><p class="generated-label">${t('Generated draft · deterministic demo · fully editable','जनरेट किया ड्राफ़्ट · नियम-आधारित डेमो · संपादन योग्य')}</p><div class="two-panel">${['en','hi'].map(l=>`<div class="translation-box"><h3>${l==='en'?'English':'हिन्दी'}</h3><label for="bridge-${l}">${l==='en'?'Introduction & project explanation':'परिचय और प्रोजेक्ट की व्याख्या'}</label><textarea id="bridge-${l}" data-draft="${l}" lang="${l}" style="min-height:370px">${e(drafts[l]??'')}</textarea><p class="helper">${l==='en'?'Edit or remove any generated text.':'जनरेट किया टेक्स्ट बदलें या हटाएं।'}</p></div>`).join('')}</div><div class="actions">${button(t('Copy both versions','दोनों संस्करण कॉपी करें'),'copy-bridge','secondary','link')}${button(t('Clear drafts','ड्राफ़्ट हटाएं'),'clear-bridge','text')}</div></section><div class="actions">${button(t('Next: prepare with a mentor','अगला: मेंटर के साथ तैयारी'),'go-mentor')}</div>`}
function mentorView(){return `${title(t('Different perspectives. Shared progress.','अलग नज़रिए। साझा प्रगति।'),t('A focused space for a beginner and mentor to understand each other.','शुरुआती छात्र और मेंटर के लिए एक-दूसरे को समझने की जगह।'))}<div class="notice">${t('Experience is individual. Age and language do not determine technical ability. This is conversation preparation, not a messaging service.','हर व्यक्ति का अनुभव अलग है। उम्र और भाषा तकनीकी क्षमता तय नहीं करतीं। यह बातचीत की तैयारी है, मैसेजिंग सेवा नहीं।')}</div><div class="two-panel"><section class="card"><div class="card-header"><h2>${t('The beginner’s perspective','सीखने वाले का नज़रिया')}</h2><span class="badge project">${t('YOUR VOICE','आपकी बात')}</span></div><label for="mentor-goals">${t('Goals, current skills, and questions · English or Hindi','लक्ष्य, मौजूदा कौशल और सवाल · अंग्रेज़ी या हिन्दी')}</label><textarea class="large" id="mentor-goals" placeholder="${t('What are you hoping to learn? Where would guidance help?','आप क्या सीखना चाहते हैं? कहां मदद चाहिए?')}">${e(mentor.goals)}</textarea><p class="helper">${t('Your current passport and opportunity will inform the suggested questions.','सुझाए सवाल आपके पासपोर्ट और अवसर पर आधारित होंगे।')}</p></section><section class="card"><div class="card-header"><h2>${t('The mentor’s perspective','मेंटर का नज़रिया')}</h2><span class="badge self">${t('THEIR VOICE','उनकी बात')}</span></div><label for="mentor-feedback">${t('Expectations or feedback · English or Hindi','अपेक्षाएं या प्रतिक्रिया · अंग्रेज़ी या हिन्दी')}</label><textarea class="large" id="mentor-feedback" placeholder="${t('What would a useful first contribution look like? What support can you offer?','पहला उपयोगी योगदान कैसा हो? आप क्या मदद दे सकते हैं?')}">${e(mentor.feedback)}</textarea><p class="helper">${t('Leave blank if you have not spoken yet. We won’t invent a mentor’s feedback.','अभी बातचीत नहीं हुई है तो खाली छोड़ें। हम मेंटर की प्रतिक्रिया नहीं गढ़ेंगे।')}</p></section></div><div class="actions">${button(t('Prepare a discussion guide','संवाद गाइड तैयार करें'),'generate-mentor','','spark')}</div>${drafts.mentor!==undefined?`<section class="card" style="margin-top:20px"><div class="card-header"><h2>${t('Your shared starting point','आपकी साझा शुरुआत')}</h2><span class="badge self">${t('Generated · editable template','जनरेट किया · संपादन योग्य टेम्पलेट')}</span></div><p class="intro">${t('Bilingual framing and questions; free-text contributions remain in their original language. Review together.','द्विभाषी रूपरेखा और सवाल; योगदान का टेक्स्ट मूल भाषा में है। साथ में समीक्षा करें।')}</p><label for="mentor-summary">${t('Discussion guide','संवाद गाइड')}</label><textarea id="mentor-summary" style="min-height:330px">${e(drafts.mentor)}</textarea><div class="actions">${button(t('Copy guide','गाइड कॉपी करें'),'copy-mentor','secondary','link')}${button(t('Remove guide','गाइड हटाएं'),'clear-mentor','text')}${button(t('Preview Skill Passport','स्किल पासपोर्ट देखें'),'go-preview')}</div></section>`:''}`}
function preview(){const p=shareProfile||profile;return `${title(t('A passport to possibility.','संभावनाओं का पासपोर्ट।'),t('A human story, supported by evidence. No overall score.','प्रमाण के साथ एक इंसानी कहानी। कोई समग्र स्कोर नहीं।'),!shareProfile?button(t('Edit passport','पासपोर्ट बदलें'),'go-passport','secondary'):button(t('Create your own','अपना बनाएं'),'exit-share','secondary'))}<section class="card"><div class="preview-header"><div class="avatar">${e(initials(p.name))}</div><h2>${e(p.name)}</h2><p>${e(p.headline)}</p><p>${e(p.goal)}</p></div><h2 class="section-title">${t('Skills & evidence','कौशल और प्रमाण')}</h2>${[...new Set([...p.skills,...p.projects.flatMap(x=>x.skills)])].map(s=>`<div class="evidence-row"><strong>${e(s)}</strong>${badge(p.projects.some(x=>x.evidenceType!=='self-reported-video'&&x.description.trim()&&x.skills.includes(s))?'project':'self')}</div>`).join('')}<h2 style="margin-top:25px">${t('Projects & learning achievements','प्रोजेक्ट और सीखने की उपलब्धियां')}</h2>${projectCards(p)}<div class="notice" style="margin-top:20px;margin-bottom:0">${t('Evidence labels describe what is recorded, not independent verification. Project claims are supplied by the profile owner. No independent reviews have been recorded.','प्रमाण के लेबल दर्ज जानकारी दिखाते हैं, स्वतंत्र सत्यापन नहीं। प्रोजेक्ट के दावे प्रोफ़ाइल के मालिक ने दिए हैं। कोई स्वतंत्र समीक्षा दर्ज नहीं है।')}</div></section><div class="actions">${!shareProfile?button(t('Create shareable link','साझा करने का लिंक बनाएं'),'share','','link'):''}${button(t('Download passport','पासपोर्ट डाउनलोड करें'),'export','secondary','passport')}${button(t('Print / Save PDF','प्रिंट / PDF सहेजें'),'print','secondary')}</div><p class="privacy">${t('Sharing includes your name, goals, skills, and projects in the URL. Anyone with the link can read them. Localhost links only work on this computer; to share remotely, host these static files or send the downloaded passport.','लिंक में नाम, लक्ष्य, कौशल और प्रोजेक्ट शामिल हैं। लिंक वाला कोई भी व्यक्ति पढ़ सकता है। Localhost लिंक केवल इसी कंप्यूटर पर चलते हैं; दूर साझा करने के लिए फ़ाइलें होस्ट करें या डाउनलोड किया पासपोर्ट भेजें।')}</p>`}
async function copy(text){if(!text.trim()){toast(t('Generate or write a draft first.','पहले ड्राफ़्ट बनाएं या लिखें।'));return;}try{await navigator.clipboard.writeText(text);toast(t('Copied to clipboard.','क्लिपबोर्ड पर कॉपी हुआ।'));}catch{const dialog=document.querySelector('#editor');dialog.innerHTML=`<div class="dialog-head"><h2>${t('Copy this text','यह टेक्स्ट कॉपी करें')}</h2><button class="icon-button" data-close aria-label="Close">×</button></div><textarea readonly aria-label="Text to copy">${e(text)}</textarea>`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.showModal();dialog.querySelector('textarea').select();}}
function invalidate(){drafts={};completed=[];}
function projectEditor(index){const p=index===undefined?{title:'',description:'',skills:[],url:'',achievement:''}:profile.projects[index];const dialog=document.querySelector('#editor');dialog.innerHTML=`<div class="dialog-head"><h2>${t(index===undefined?'Add a project':'Edit project',index===undefined?'प्रोजेक्ट जोड़ें':'प्रोजेक्ट बदलें')}</h2><button class="icon-button" data-close aria-label="Close">×</button></div><form id="project-form"><div class="field"><label>${t('Project title','प्रोजेक्ट का नाम')}<input name="title" required maxlength="120" value="${e(p.title)}"></label></div><div class="field"><label>${t('What did you build? What was your contribution?','क्या बनाया? आपका योगदान क्या था?')}<textarea name="description" required minlength="20" maxlength="3000">${e(p.description)}</textarea></label></div><div class="field"><label>${t('Skills demonstrated · comma separated','प्रदर्शित कौशल · कॉमा से अलग करें')}<input name="skills" required maxlength="1000" value="${e(p.skills.join(', '))}"></label></div><div class="field"><label>${t('Project link · optional, http(s) only','प्रोजेक्ट लिंक · वैकल्पिक, केवल http(s)')}<input name="url" type="url" value="${e(p.url)}" placeholder="https://…"></label></div><div class="field"><label>${t('Learning achievement · optional, self-reported','सीखने की उपलब्धि · वैकल्पिक, स्वयं बताई')}<input name="achievement" maxlength="300" value="${e(p.achievement||'')}"></label></div><p class="helper">${t('Only claim skills this project actually uses. A description is not independent verification.','केवल वे कौशल बताएं जो इस प्रोजेक्ट में इस्तेमाल किए हैं। विवरण स्वतंत्र सत्यापन नहीं है।')}</p><p id="project-error" class="error" role="alert"></p><div class="actions"><button class="button" type="submit">${t('Save project','प्रोजेक्ट सहेजें')}</button><button class="button secondary" type="button" data-close>${t('Cancel','रद्द करें')}</button></div></form>`;dialog.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>dialog.close());dialog.querySelector('form').onsubmit=event=>{event.preventDefault();const f=new FormData(event.target);const project={id:p.id||crypto.randomUUID(),title:f.get('title').trim(),description:f.get('description').trim(),skills:parseSkills(f.get('skills')),url:f.get('url').trim(),achievement:f.get('achievement').trim()};if(!project.title||project.description.length<20||!project.skills.length|| (project.url&&!safeURL(project.url))){dialog.querySelector('#project-error').textContent=t('Add a title, at least 20 characters of description, skills, and a valid http(s) link if provided.','नाम, कम से कम 20 अक्षरों का विवरण, कौशल और सही http(s) लिंक जोड़ें।');return;}if(index===undefined)profile.projects.push(project);else profile.projects[index]=project;invalidate();persist();dialog.close();render();toast(t('Project saved. Evidence mapping updated.','प्रोजेक्ट सहेजा गया। प्रमाण अपडेट हुए।'));};dialog.showModal();}
function parseSkills(value){return [...new Set(value.split(',').map(s=>s.trim()).filter(Boolean).map(s=>CATALOG.find(c=>c.id.toLowerCase()===s.toLowerCase())?.id||s))];}
function generateMentor(){const gaps=result().requirements.filter(x=>x.status!=='demonstrated').map(x=>x.id);drafts.mentor=`DISCUSSION GUIDE / संवाद गाइड\n\nBeginner’s perspective / सीखने वाले का नज़रिया (original wording / मूल शब्द):\n${mentor.goals.trim()||profile.goal}\n\nMentor’s perspective / मेंटर का नज़रिया (original wording / मूल शब्द):\n${mentor.feedback.trim()||'Not shared yet / अभी साझा नहीं किया गया'}\n\nEvidence to discuss / चर्चा के लिए प्रमाण:\n${decoded?(gaps.join(', ')||'Review project artifacts together / प्रोजेक्ट प्रमाण साथ में देखें'):'Decode an opportunity to identify gaps / अंतर पहचानने के लिए अवसर समझें'}\n\nSuggested questions / सुझाए सवाल:\n1. What would a useful first contribution look like?\nपहला उपयोगी योगदान कैसा होना चाहिए?\n2. ${gaps.length?'Which example would best demonstrate '+gaps[0]+'?':'Which project should we review together?'}\n${gaps.length?gaps[0]+' का प्रमाण दिखाने के लिए कौन सा उदाहरण अच्छा होगा?':'कौन सा प्रोजेक्ट हम साथ में देखें?'}\n3. What support can the mentor offer, and what can the beginner try independently?\nमेंटर क्या मदद दे सकते हैं और सीखने वाला खुद क्या आज़मा सकता है?\n4. What is one small next step and when shall we check in?\nअगला छोटा कदम क्या हो और अगली बातचीत कब करें?\n\nAgreed next step / सहमत अगला कदम: ____________________`;persist();render();toast(t('Discussion guide prepared. Review it together.','संवाद गाइड तैयार है। साथ समीक्षा करें।'));}
function exportPassport(){const p=shareProfile||profile;const body=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(p.name)} — ${e(BRAND)} Skill Passport</title><style>body{font:16px/1.7 system-ui,sans-serif;max-width:780px;margin:50px auto;padding:24px;color:#264f3c}h1{font-size:36px}article{border:1px solid #dfe5d8;padding:20px;margin:18px 0;border-radius:12px}.badge{background:#edf2e5;padding:4px 8px;font-size:12px;border-radius:6px}.tags{display:flex;gap:8px}.tag{padding:3px 7px;border:1px solid #ddd;font-size:12px}a{color:#245441}.helper{font-size:12px;color:#66755c}.project-top{display:flex;justify-content:space-between;align-items:center}h3{margin:0}</style><h1>${e(p.name)}</h1><p>${e(p.headline)}</p><p>${e(p.goal)}</p><h2>Skills / कौशल</h2>${[...new Set([...p.skills,...p.projects.flatMap(x=>x.skills)])].map(s=>`<p>${e(s)} — ${p.projects.some(x=>x.evidenceType!=='self-reported-video'&&x.description.trim()&&x.skills.includes(s))?'Project-demonstrated / प्रोजेक्ट से प्रदर्शित':'Self-reported / स्वयं बताया गया'}</p>`).join('')}<h2>Projects & learning / प्रोजेक्ट और सीख</h2>${projectCards(p)}<p class="helper">Project claims are supplied by the owner, not independently verified. No independent reviews recorded. / प्रोजेक्ट के दावे मालिक ने दिए हैं, स्वतंत्र सत्यापन नहीं हुआ है।</p><p class="helper">Created with ${e(BRAND)} · Evidence, not a score.</p></html>`;const url=URL.createObjectURL(new Blob([body],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='aperture-ai-skill-passport.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Passport downloaded as a standalone web page.','पासपोर्ट स्वतंत्र वेब पेज के रूप में डाउनलोड हुआ।'));}
function bind(){document.querySelector('#activity-video')?.addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;if(!file.type.startsWith('video/')){toast(t('Choose a valid video file.','सही वीडियो फ़ाइल चुनें।'));return;}if(file.size>100*1024*1024){toast(t('Choose a video under 100 MB.','100 MB से छोटी वीडियो फ़ाइल चुनें।'));return;}if(activityVideoURL)URL.revokeObjectURL(activityVideoURL);activityFile=file;activityDraft=null;videoConsent=false;activityVideoURL=URL.createObjectURL(file);render();});document.querySelector('#video-consent')?.addEventListener('change',event=>{videoConsent=event.target.checked;document.querySelector('[data-action="analyze-video"]').disabled=!videoConsent||!activityVideoURL||!aiConfigured||busy;});document.querySelector('#activity-form')?.addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.target),project={id:crypto.randomUUID(),title:f.get('title').trim(),description:f.get('description').trim(),skills:parseSkills(f.get('skills')),url:'',evidenceType:'ai-video-reviewed',artifactLabel:activityDraft?.videoName||'',achievement:'Activity description reviewed by profile owner.',improvements:f.get('improvement').trim()?f.get('improvement').trim().split('\n').filter(Boolean):[]};if(project.description.length<20){toast(t('Add a little more detail before saving.','सहेजने से पहले थोड़ा और विवरण लिखें।'));return;}profile.projects.push(project);ratingHistory=recordSkillRatings(ratingHistory,activityDraft?.skills,project.title);profile.skills=[...new Set([...profile.skills,...project.skills])];activityDraft=null;invalidate();persist();navigate('passport');toast(t('Reviewed activity added to your passport.','जांची गई गतिविधि पासपोर्ट में जुड़ गई।'));});document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>navigate(el.dataset.view));document.querySelectorAll('[data-lang]').forEach(el=>el.onclick=()=>{lang=el.dataset.lang;persist();render()});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{const a=el.dataset.action;if(a.startsWith('go-')){navigate(a.slice(3));return;}if(a==='analyze-video'){if(!activityFile||!videoConsent){toast(t('Choose a video and agree to AI analysis first.','वीडियो चुनें और AI विश्लेषण की सहमति दें।'));return;}try{busy=true;el.disabled=true;el.innerHTML=t('Uploading video for analysis…','विश्लेषण के लिए वीडियो भेजा जा रहा है…');const response=await fetch('/api/analyze-video',{method:'POST',headers:{'Content-Type':activityFile.type||'video/mp4','X-Aperture-Language':lang},body:activityFile});const payload=await response.json();if(!response.ok)throw Error(payload.error||t('Analysis failed. Please try again.','विश्लेषण विफल। फिर कोशिश करें।'));const x=payload.analysis;activityDraft={title:x.activity_title,description:x.activity_summary+'\n\n'+x.form_description,skills:x.suggested_skills,improvements:x.improvements,strengths:x.strengths,standardNote:x.standard_note,standardAvailable:x.standard_available,uncertainty:x.uncertainty,videoName:activityFile.name,model:payload.model};render();document.querySelector('#activity-generated')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(err){toast(err.message||t('Could not analyze video. Check server setup and try again.','वीडियो का विश्लेषण नहीं हो सका। सर्वर सेटअप जांचें।'));}finally{busy=false;render();}}if(a==='remove-video'){if(activityVideoURL)URL.revokeObjectURL(activityVideoURL);activityVideoURL=null;activityFile=null;render();}if(a==='discard-activity'){activityDraft=null;render();}if(a==='follow-mentor'){const id=el.dataset.id;social.follows=social.follows.includes(id)?social.follows.filter(x=>x!==id):[...social.follows,id];if(id==='mentor-priya'){classState.follows=social.follows.includes(id)?[...new Set([...classState.follows,id])]:classState.follows.filter(x=>x!==id);saveClassState(classState);}persist();render();return;}if(a==='sort-feed'){social.feedSort=el.dataset.sort==='top'?'top':'new';persist();render();return;}if(a==='join-community'){social.joined=social.joined.includes(el.dataset.id)?social.joined.filter(id=>id!==el.dataset.id):[...social.joined,el.dataset.id];persist();render();return;}if(a==='vote-post'){const post=social.posts.find(p=>p.id===el.dataset.id);if(post){const had=!!social.votes[post.id];post.votes=Math.max(0,(Number(post.votes)||0)+(had?-1:1));if(had)delete social.votes[post.id];else social.votes[post.id]=true;persist();render();}return;}if(a==='sample-decode'){opportunity=SAMPLE;decoded=true;invalidate();persist();navigate('decoder');}if(a==='load-en'||a==='load-hi'){opportunity=a==='load-en'?SAMPLE:HINDI_SAMPLE;decoded=false;invalidate();persist();render();}if(a==='add-project')projectEditor();if(a==='generate-bridge'){if((drafts.en||drafts.hi)&&!confirm(t('Replace both drafts with freshly generated text?','दोनों ड्राफ़्ट को नए टेक्स्ट से बदलें?')))return;drafts.en=bilingualText('en');drafts.hi=bilingualText('hi');persist();render();toast(t('Bilingual draft ready to edit.','द्विभाषी ड्राफ़्ट संपादन के लिए तैयार है।'));}if(a==='copy-bridge')await copy([drafts.en||'',drafts.hi||''].filter(Boolean).join('\n\n— — —\n\n'));if(a==='clear-bridge'){drafts.en='';drafts.hi='';persist();render();}if(a==='generate-mentor')generateMentor();if(a==='copy-mentor')await copy(drafts.mentor||'');if(a==='clear-mentor'){delete drafts.mentor;persist();render();}if(a==='share-profile'){const url=location.origin+'/profile#passport='+encodePassport(profile);await copy(url);toast('Profile link copied.');return;}if(a==='share'){const url=location.origin+location.pathname+'#passport='+encodePassport(profile);await copy(url);}if(a==='export')exportPassport();if(a==='print')window.print();if(a==='exit-share'){history.replaceState(null,'',location.pathname);shareProfile=null;shareError=false;navigate('home');}});

 document.querySelector('#profile-form')?.addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.target);if(!f.get('name').trim()||!f.get('headline').trim()){toast(t('Please add a name and headline.','नाम और परिचय जोड़ें।'));return;}profile={...profile,name:f.get('name').trim(),headline:f.get('headline').trim(),goal:f.get('goal').trim(),skills:parseSkills(f.get('skills'))};invalidate();persist();render();toast(t('Profile saved. Your evidence comparison is up to date.','प्रोफ़ाइल सहेजी गई। प्रमाण की तुलना अपडेट हुई।'));});
 document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>projectEditor(Number(el.dataset.edit)));document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{const index=Number(el.dataset.remove);if(!confirm(t(`Remove “${profile.projects[index].title}” and its evidence?`,`“${profile.projects[index].title}” और उसके प्रमाण हटाएं?`)))return;profile.projects.splice(index,1);invalidate();persist();render();toast(t('Project removed. Evidence updated.','प्रोजेक्ट हटाया गया। प्रमाण अपडेट हुए।'));});
 document.querySelector('#opportunity')?.addEventListener('input',event=>{opportunity=event.target.value;if(decoded){decoded=false;invalidate();document.querySelector('.section-stack')?.remove();}persist();});
 document.querySelector('#decode-form')?.addEventListener('submit',async event=>{event.preventDefault();opportunity=new FormData(event.target).get('opportunity').trim();if(opportunity.length<20){toast(t('Add at least 20 characters of opportunity context.','अवसर का कम से कम 20 अक्षरों का विवरण जोड़ें।'));return;}busy=true;decoded=false;render();await new Promise(resolve=>setTimeout(resolve,380));busy=false;decoded=true;invalidate();persist();if(view==='decoder'){render();document.querySelector('#plain-summary')?.scrollIntoView({behavior:'smooth',block:'center'});}toast(t('Decoded. Review the requirements and source excerpts.','विवरण तैयार है। अपेक्षाएं और मूल अंश जांचें।'));});
 document.querySelector('#plain-summary')?.addEventListener('input',event=>{drafts['plain-'+lang]=event.target.value;persist()});document.querySelectorAll('[data-plan]').forEach(el=>el.onchange=()=>{completed=el.checked?[...new Set([...completed,el.dataset.plan])]:completed.filter(s=>s!==el.dataset.plan);persist();el.closest('.plan-item').classList.toggle('done',el.checked);});document.querySelectorAll('[data-draft]').forEach(el=>el.oninput=()=>{drafts[el.dataset.draft]=el.value;persist()});document.querySelector('#mentor-goals')?.addEventListener('input',event=>{mentor.goals=event.target.value;persist()});document.querySelector('#mentor-feedback')?.addEventListener('input',event=>{mentor.feedback=event.target.value;persist()});document.querySelector('#mentor-summary')?.addEventListener('input',event=>{drafts.mentor=event.target.value;persist()});document.querySelector('#mentor-search')?.addEventListener('input',event=>{const q=event.target.value.trim().toLowerCase();document.querySelectorAll('.mentor-card').forEach(card=>{card.hidden=!card.dataset.search.includes(q);});});document.querySelector('#community-post-form')?.addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.target),title=f.get('title').trim(),body=f.get('body').trim();if(title.length<4||body.length<12)return;social.posts.push({id:crypto.randomUUID(),community:f.get('community'),title,body,author:profile.name,createdAt:new Date().toISOString(),votes:0,comments:[]});persist();render();toast('Discussion saved in this browser.');});document.querySelectorAll('.comment-form').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const post=social.posts.find(x=>x.id===form.dataset.postId),body=new FormData(form).get('comment').trim();if(!post||!body)return;post.comments=Array.isArray(post.comments)?post.comments:[];post.comments.push({id:crypto.randomUUID(),author:profile.name,body,createdAt:new Date().toISOString()});persist();render();toast('Comment added.');}));bindClasses({state:classState,render,navigate,toast,onFollow:()=>{if(classState.follows.includes('mentor-priya')){if(!social.follows.includes('mentor-priya'))social.follows.push('mentor-priya')}else social.follows=social.follows.filter(id=>id!=='mentor-priya');persist()}});}
render();
loadAIStatus();loadAuthConfig();
window.addEventListener('popstate',()=>{const routes={'/auth/callback':'login','/reset-password':'reset','/':'login','/welcome':'home','/profile':'profile','/classes':'classes','/classes/my-classes':'my-classes','/mentor/classes':'mentor-classes','/calendar':'calendar','/analytics':'analytics','/mentors':'mentors','/communities':'communities','/studio':'video','/passport':'passport','/opportunities':'decoder','/language':'bridge','/login/user':'login','/register/user':'register','/dashboard/user':'home','/login/mentor':'login','/register/mentor':'register','/dashboard/mentor':'mentor-classes','/auth/callback':'login','/reset-password':'reset'};view=routes[location.pathname]||'login';render();});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#passport=')){shareProfile=decodePassport(location.hash.slice(10));shareError=!shareProfile;view='preview';render();window.scrollTo(0,0);}else if(shareProfile||shareError){shareProfile=null;shareError=false;navigate('home');}});
